`timescale 1ns / 1ps
// Auto-generated NIST CAVP KAT Verification Testbench
module tb_nist_kat_runner;
    reg          clk;
    reg          rst;
    reg          start;
    reg          mode;
    reg  [127:0] key;
    reg  [127:0] block_in;
    wire [127:0] block_out;
    wire         done;
    wire         busy;
    integer errors;
    integer total_tests;

    initial begin clk = 0; forever #5 clk = ~clk; end

    aes_core dut (
        .clk(clk), .rst(rst), .start(start), .mode(mode),
        .key(key), .block_in(block_in), .block_out(block_out),
        .done(done), .busy(busy)
    );

    task run_test;
        input        t_mode;
        input [127:0] t_key;
        input [127:0] t_in;
        input [127:0] t_exp;
        input [8*40-1:0] t_name;
        begin
            @(posedge clk);
            mode     <= t_mode;
            key      <= t_key;
            block_in <= t_in;
            start    <= 1'b1;
            @(posedge clk);
            start    <= 1'b0;
            while (!done) @(posedge clk);
            if (block_out !== t_exp) begin
                $display("  [FAIL] %s", t_name);
                $display("    Expected: %h", t_exp);
                $display("    Got:      %h", block_out);
                errors = errors + 1;
            end
            total_tests = total_tests + 1;
            @(posedge clk);
        end
    endtask

    initial begin
        errors = 0;
        total_tests = 0;
        rst = 1; start = 0; mode = 0; key = 0; block_in = 0;
        repeat(2) @(posedge clk);
        rst = 0; @(posedge clk);
        $display("========================================");
        $display("Running NIST CAVP KAT Verification Suite");
